/**
 * WP-02 — schema for `src/config/pricing.json`. That file does NOT exist
 * yet: WP-04 creates it, sourcing every number from Anthropic's published
 * pages and recording the exact provenance in the config itself (`source`,
 * `pricesAsOf`):
 *
 * - Base model rates: https://platform.claude.com/docs/en/about-claude/pricing
 * - Cache read/write multipliers:
 *   https://platform.claude.com/docs/en/build-with-claude/prompt-caching#pricing
 *
 * Rates are USD per million tokens at published Anthropic API rates (D2).
 * Unknown model ids are never guessed — see the degradation policy in
 * `contract.ts`.
 */

export interface CacheMultipliers {
  /** Cache read, × base input rate (published: 0.1). */
  read: number
  /** 5m-TTL cache write, × base input rate (published: 1.25). */
  write5m: number
  /** 1h-TTL cache write, × base input rate (published: 2.0). */
  write1h: number
}

export interface ModelPricing {
  /** Human-readable name for the UI, e.g. "Claude Opus 5". */
  displayName: string
  /** Base input rate, USD per 1M tokens. */
  inputPerMTok: number
  /** Output rate, USD per 1M tokens. */
  outputPerMTok: number
  /**
   * Keyed by observed `usage.service_tier` values ("standard", "batch", ...),
   * applied to input-side and output rates. Missing key or map = 1.0;
   * "standard" MUST be 1.0 when present.
   */
  serviceTierMultipliers?: Record<string, number>
  /**
   * Keyed by observed `usage.speed` values (e.g. "fast" = 2.0 on Opus 5).
   * Same defaulting rule as tiers.
   */
  speedMultipliers?: Record<string, number>
}

export interface PricingConfig {
  /** ISO date shown beside every dollar figure in the UI (decision D5). */
  pricesAsOf: string
  /**
   * Direct URL of the published Anthropic pricing page the numbers were
   * taken from (see the header) — required, so every rate is auditable.
   */
  source: string
  cacheMultipliers: CacheMultipliers
  /** Keyed by raw `message.model` ids, e.g. "claude-opus-5". */
  models: Record<string, ModelPricing>
}
=== config/pricing.ts head ===
/**
 * WP-04 — the shipped pricing config (decision D5): rates live in
 * `pricing.json`, keyed by raw `message.model` ids, with a `pricesAsOf`
 * date the UI shows beside every dollar figure. Every number comes from
 * the published page named in `source`; nothing is guessed.
 *
 * Provenance and policy (all from that page as of `pricesAsOf`):
 *  - Base input/output rates from the "Model pricing" table; cache
 *    multipliers (0.1x read, 1.25x 5m write, 2x 1h write) from "Prompt
 *    caching".
 *  - `batch` = 0.5 on input and output ("Batch processing"); caching
 *    multipliers stack on top.
 *  - `fast` = 2 on Claude Opus 5 / Opus 4.8 only ($10 / $50 per MTok, with
 *    caching multipliers stacking); Opus 4.6 runs fast-mode requests at
 *    standard speed and standard rates (explicit 1); other models reject
 *    or ignore it (no entry, so the schema's default of 1 applies).
 *  - `priority` = 1: Priority Tier is a pre-purchased capacity commitment,
 *    not a per-token premium, so those requests are shown at standard
 *    rates.
 *  - Not modeled: the 1.1x `inference_geo: "us"` data-residency multiplier
 *    (the parser does not carry `inference_geo`; see docs/PLAN.md WP-04).
 *  - Dated ids (e.g. `claude-opus-4-5-20251101`) duplicate their alias
 *    entries because older Claude Code versions wrote dated ids.
 *
 * To update: edit `pricing.json`, bump `pricesAsOf`, run `npm test` (the
 * config is validated on load and in `cost.test.ts`).
 */

import type { PricingConfig } from '../engine/pricing'
import { validatePricingConfig } from '../engine/cost'
import raw from './pricing.json'

export const PRICING: PricingConfig = validatePricingConfig(raw)

