            {verdict && (
              <span
                className={`shrink-0 font-mono text-[10.5px] ${
                  active ? 'text-primary' : 'text-slate-500'
                }`}
              >
                {verdict.ttl}
              </span>
            )}
          </span>
        )}
      </button>
    </li>
  )
}

/** What the money column shows when there is no verdict to show. */
function StatusMark({ entry }: { entry: SessionEntry }) {
  const { t } = useTranslation()
  switch (entry.status.phase) {
    case 'rejected':
    case 'failed':
      return <span className="text-red">!</span>
    case 'cancelled':
      return <span className="font-normal text-slate-400">{t('status.cancelled')}</span>
    default:
      return null
  }
}
