    const fake = createFakeWorker(createStubEngine())
    const runner = createAnalysisRunner({ createWorker: () => fake.port })
    runner.start(request(), spyHandlers())
    expect(() => runner.start(request(), spyHandlers())).toThrow(/already running/)
